class TreeBuilder:
    """Base tree builder that constructs a DOM tree from tokens."""

    def __init__(self, namespaceHTMLElements=True):
        self.namespaceHTMLElements = namespaceHTMLElements

    def insertDoctype(self, token):
        pass

    def insertComment(self, token, parent=None):
        pass

    def insertElement(self, token):
        pass

    def insertText(self, token):
        pass


def getTreeBuilder(treebuilder_type, implementation=None, **kwargs):
    """Get a tree builder instance."""
    return TreeBuilder(**kwargs)

"""Base tree walker that yields tokens from a token stream."""


class TreeWalker:
    """Base tree walker."""

    def __init__(self, tokens):
        self._tokens = tokens

    def __iter__(self):
        return iter(self._tokens)


class NonRecursiveTreeWalker(TreeWalker):
    """Non-recursive tree walker."""

    def getTreeWalker(self, tree, *args, **kwargs):
        return TreeWalker(tree)


def getTreeWalker(tree, *args, **kwargs):
    """Get a tree walker for the given tree."""
    if isinstance(tree, list):
        return TreeWalker(tree)
    return TreeWalker(tree)

